package au.edu.uow.csci318.activity.domain;import jakarta.persistence.*;import java.time.*;import java.util.*;
@Entity @Table(name="study_sessions") public class StudySession{@Id private UUID id;@Column(nullable=false)private UUID subjectId;@Column(nullable=false)private int durationMinutes;@Column(nullable=false)private LocalDate studyDate;@Column(nullable=false)private String description;@Column(nullable=false)private Instant recordedAt;protected StudySession(){}public StudySession(UUID subjectId,int minutes,LocalDate date,String description){id=UUID.randomUUID();this.subjectId=Objects.requireNonNull(subjectId);if(minutes<=0||minutes>1440)throw new IllegalArgumentException("Study duration must be between 1 and 1440 minutes");durationMinutes=minutes;studyDate=Objects.requireNonNull(date);if(studyDate.isAfter(LocalDate.now()))throw new IllegalArgumentException("Study date cannot be in the future");if(description==null||description.isBlank())throw new IllegalArgumentException("Activity description is required");this.description=description.trim();recordedAt=Instant.now();}public UUID getId(){return id;}public UUID getSubjectId(){return subjectId;}public int getDurationMinutes(){return durationMinutes;}public LocalDate getStudyDate(){return studyDate;}public String getDescription(){return description;}public Instant getRecordedAt(){return recordedAt;}}
